    _updateBriefing(state) {
      var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
      var round = this.ROUNDS[idx];
      var tr = function (key) {
        return window.mySimulation && window.mySimulation.t ? window.mySimulation.t(key) : key;
      };
      var c1 = document.getElementById("scoreChart");
      if (c1) c1.setAttribute("aria-label", tr("chart_alt_score"));
      var c2 = document.getElementById("relationshipChart");
      if (c2) c2.setAttribute("aria-label", tr("chart_alt_relationship"));
      var briefEl = document.getElementById("briefingText");
      if (briefEl) briefEl.innerHTML = tr(round.descKey);
      var eventPanel = document.getElementById("eventPanel");
      var eventIcon = document.getElementById("eventIcon");
      var eventText = document.getElementById("eventText");
      if (eventPanel && state.domainState && state.domainState.activeEvent && state.domainState.eventApplied) {
        eventPanel.style.display = "flex";
        eventIcon.innerHTML = state.domainState.activeEvent.icon;
        eventText.innerHTML = tr(state.domainState.activeEvent.textKey);
      } else if (eventPanel) {
        eventPanel.style.display = "none";
      }
    }
  }
  document.addEventListener("DOMContentLoaded", function () {
    window.mySimulation = new USF.SimulationFramework();
    window.mySimulation.initialize(new LaborDeskAdapter(), { simulationType: "labordesk_collective_bargaining", maxPeriods: 4, autoSaveInterval: 30000 });
  });
